if(!defined('ABSPATH'))exit;
function dgs_es_widget($type,$settings=array()){return dgs_elementor_widget($type,$settings);}
function dgs_es_heading($text,$tag='h2',$size=22,$align='right'){return dgs_es_widget('heading',array('title'=>$text,'header_size'=>$tag,'title_color'=>'#511c72','align'=>$align,'typography_typography'=>'custom','typography_font_size'=>array('size'=>$size,'unit'=>'px'),'typography_font_size_mobile'=>array('size'=>$tag==='h1'?28:19,'unit'=>'px'),'typography_font_weight'=>'800','typography_line_height'=>array('size'=>1.6,'unit'=>'em')));}
function dgs_es_text($text,$align='right'){return dgs_es_widget('text-editor',array('editor'=>wpautop(esc_html($text)),'align'=>$align,'text_color'=>'#654879','typography_typography'=>'custom','typography_font_size'=>array('size'=>14,'unit'=>'px'),'typography_line_height'=>array('size'=>1.9,'unit'=>'em')));}
function dgs_es_button($text,$url,$purple=false){return dgs_es_widget('button',array('text'=>$text,'link'=>array('url'=>$url),'align'=>'center','background_color'=>$purple?'#7b28a4':'#ffcd35','button_text_color'=>$purple?'#ffffff':'#4e255c','border_radius'=>array('unit'=>'px','top'=>'20','right'=>'20','bottom'=>'20','left'=>'20','isLinked'=>true),'button_padding'=>array('unit'=>'px','top'=>'9','right'=>'20','bottom'=>'9','left'=>'20','isLinked'=>false),'typography_typography'=>'custom','typography_font_size'=>array('size'=>13,'unit'=>'px'),'typography_font_weight'=>'700'));}
function dgs_es_picture($setting,$height=220,$caption=''){$id=absint(dgs_showcase_setting($setting));$ref='hero';if(preg_match('/gallery_image_([0-3])/',$setting,$m))$ref='gallery'.$m[1];return dgs_es_widget('dgs_picture',array('image'=>array('id'=>$id,'url'=>$id?(wp_get_attachment_image_url($id,'large')?:''):''),'reference'=>$ref,'alt'=>$caption?:'نمای مدرسه دانشگران','caption'=>$caption,'priority'=>$setting==='hero_image'?'yes':'','height'=>array('size'=>$height,'unit'=>'px'),'height_mobile'=>array('size'=>min($height,210),'unit'=>'px'),'radius'=>array('size'=>14,'unit'=>'px')));}
function dgs_es_live($kind,$extra=array()){return dgs_es_widget('dgs_live',array_merge(array('kind'=>$kind,'count'=>6,'columns'=>'3','columns_tablet'=>'2','columns_mobile'=>'1'),$extra));}
function dgs_es_column($widgets,$width=100,$card=false){$settings=array('_column_size'=>$width,'padding'=>array('unit'=>'px','top'=>'15','right'=>'15','bottom'=>'15','left'=>'15','isLinked'=>true));if($card)$settings=array_merge($settings,array('background_background'=>'classic','background_color'=>'#f8f2fe','border_border'=>'solid','border_width'=>array('unit'=>'px','top'=>'1','right'=>'1','bottom'=>'1','left'=>'1','isLinked'=>true),'border_color'=>'#dac0ee','border_radius'=>array('unit'=>'px','top'=>'15','right'=>'15','bottom'=>'15','left'=>'15','isLinked'=>true),'margin'=>array('unit'=>'px','top'=>'0','right'=>'5','bottom'=>'0','left'=>'5','isLinked'=>false)));return array('id'=>substr(md5(wp_rand().'dsecol'),0,7),'elType'=>'column','settings'=>$settings,'elements'=>$widgets);}
function dgs_es_section($columns,$card=true,$extra=array()){$settings=array('content_width'=>array('unit'=>'px','size'=>1200),'layout'=>'full_width','gap'=>'no','column_position'=>'middle','css_classes'=>'dse-section','margin'=>array('unit'=>'px','top'=>'0','right'=>'0','bottom'=>'16','left'=>'0','isLinked'=>false),'padding'=>array('unit'=>'px','top'=>'0','right'=>'0','bottom'=>'0','left'=>'0','isLinked'=>true));if($card)$settings=array_merge($settings,array('background_background'=>'gradient','background_color'=>'#ffffff','background_color_b'=>'#f6efff','background_gradient_angle'=>array('unit'=>'deg','size'=>125),'border_border'=>'solid','border_width'=>array('unit'=>'px','top'=>'1','right'=>'1','bottom'=>'1','left'=>'1','isLinked'=>true),'border_color'=>'#dac0ee','border_radius'=>array('unit'=>'px','top'=>'15','right'=>'15','bottom'=>'15','left'=>'15','isLinked'=>true)));return array('id'=>substr(md5(wp_rand().'dsesec'),0,7),'elType'=>'section','settings'=>array_merge($settings,$extra),'elements'=>$columns);}
function dgs_es_gallery(){return array(dgs_gallery_elementor_section());}
